dynamicOperations.source:
host.append(
        make(root, 'p', 'hint compact-hint', 'Add a step, choose a template, or switch to Code.'),
      )

list.append(
            el('button', {
              class: 'wc-tab',
              id,
              type: 'button',
              role: 'tab',
              text: title,
              tabindex: index === 0 ? '0' : '-1',
              'aria-selected': String(index === 0),
              'aria-controls': `${id}-panel`,
            }),
          )

gallery.append(
        group(
          'navigation',
          '03 / Navigation',
          'Arrow keys · Home / End · visible focus',
          card(
            'Segmented / single selection',
            stack(
              segmented(['Solid', 'Outline', 'Both']),
              el('p', { class: 'gallery-note', text: 'Arrows select; Tab exits the group.' }),
              segmented(['Available', 'Locked'], 'Availability example'),
            ),
          ),
          card(
            'Tabs / associated panels',
            tabs([
              ['Properties', 'Silicon · crystalline substrate. Thickness: 0.250 µm.'],
              ['Appearance', 'Display settings are independent of the physical model.'],
              ['Notes', 'This is a component specimen, not a proposed workstation layout.'],
            ]),
          ),
          card(
            'Tree item / hierarchy',
            el(
              'ul',
              { class: 'wc-tree', role: 'tree', 'aria-label': 'Component sample layers' },
              treeItem('Material set', [
                treeItem('Silicon substrate', [], { selected: true }),
                treeItem('Silicon dioxide'),
                treeItem('Aluminium · unavailable', [], { disabled: true }),
              ]),
              treeItem('Reference material'),
            ),
            el('p', {
              class: 'gallery-note',
              text: 'Left / Right collapse or expand; Enter selects.',
            }),
          ),
        ),
      )

gallery.append(
        group(
          'surfaces',
          '04 / Surfaces',
          'Anchored popover · native modal · collapsible section',
          card(
            'Section / disclosure',
            stack(
              section('Expanded properties', readout([['Thickness', '0.250', 'µm']])),
              section(
                'Collapsed properties',
                el('p', { text: 'Details are revealed on demand.' }),
                false,
              ),
            ),
          ),
          card(
            'Popover / non-modal',
            stack(
              el(
                'div',
                { class: 'wc-popover gallery-surface-preview' },
                el('h4', { class: 'wc-surface-title', text: 'Display options' }),
                el('p', {
                  class: 'wc-surface-copy',
                  text: 'A compact surface anchored to its trigger. Escape or outside click closes it.',
                }),
                popoverTrigger,
              ),
            ),
          ),
          card(
            'Dialog / modal',
            stack(
              el('p', {
                class: 'wc-surface-copy',
                text: 'Focus stays inside while open. Escape closes and returns focus to the trigger.',
              }),
              row(dialogTrigger),
              el('p', { class: 'gallery-note', text: '400 px maximum · viewport-safe height' }),
            ),
          ),
        ),
      )

gallery.append(
        group(
          'feedback',
          '05 / Feedback & inspection',
          'Text + semantics, not color alone · tabular numeric readouts',
          card(
            'Status / four tones',
            stack(
              status('Ready for inspection.'),
              status('Validation complete.', 'success'),
              status('Check the selected units.', 'warning'),
              status('Thickness must be positive.', 'danger'),
            ),
          ),
          card(
            'Badge & readout',
            stack(
              row(
                badge('Draft'),
                badge('Ready', 'success'),
                badge('Review', 'warning'),
                badge('Invalid', 'danger'),
              ),
              readout([
                ['Thickness', '0.250', 'µm'],
                ['Offset', '−1.200', 'µm'],
                ['Film', '10.000', 'nm'],
                ['Material regions', '24', ''],
              ]),
            ),
          ),
          card(
            'Tooltip & toast',
            stack(
              row(tooltipTrigger),
              el('div', {
                class: 'wc-tooltip gallery-surface-preview',
                text: '11 px helper text · available on focus as well as hover.',
              }),
              row(button('Show toast', { id: 'show-toast' })),
              el('p', {
                class: 'gallery-note',
                text: 'Live status announcement; dismiss explicitly.',
              }),
            ),
          ),
        ),
      )

gallery.append(
        group(
          'input-targets',
          '06 / Pointer targets',
          'Hit area changes with pointer precision; text stays 11–13 px',
          card('Automatic / actual pointer', targetExample()),
          card('Coarse / explicit specimen', targetExample(true)),
          card(
            'Sizing contract',
            readout([
              ['Fine · sm / md', '28 / 32', 'px'],
              ['Coarse · minimum', '40 × 40', 'px'],
              ['Text · unchanged', '12 / 13', 'px'],
            ]),
            el('p', {
              class: 'gallery-note',
              text: 'Coarse sizing also applies to tabs, tree rows, disclosure summaries, popover/dialog controls and toast dismissal. Non-interactive badges stay compact.',
            }),
          ),
        ),
      )

group.append(
              svgNode('rect', {
                ...attrs,
                x: Math.min(shape.a[0], shape.b[0]),
                y: Math.min(shape.a[1], shape.b[1]),
                width: Math.abs(shape.b[0] - shape.a[0]),
                height: Math.abs(shape.b[1] - shape.a[1]),
              }),
            )

group.append(
              svgNode('circle', { ...attrs, cx: shape.c[0], cy: shape.c[1], r: shape.r }),
            )

group.append(
          svgNode('line', {
            x1: section.ax,
            y1: section.ay,
            x2: section.bx,
            y2: section.by,
            stroke: 'var(--wc-text)',
            'vector-effect': 'non-scaling-stroke',
          }),
        )

svg.append(
          svgNode('rect', {
            x: 18,
            y: 12 + i * height,
            width: 444,
            height,
            fill: layer?.color || 'var(--wc-border)',
          }),
        )

viewTools.append(
        button('', `maximize:${name}`, 'maximize', {
          'aria-label': `${label} ${state.maximize === name ? 'restore' : 'maximize'}`,
          title: state.maximize === name ? 'Restore view' : 'Maximize view',
        }),
      )

group.append(
          svgNode('rect', {
            ...attrs,
            x: Math.min(shape.a[0], shape.b[0]),
            y: Math.min(shape.a[1], shape.b[1]),
            width: Math.abs(shape.b[0] - shape.a[0]),
            height: Math.abs(shape.b[1] - shape.a[1]),
          }),
        )

group.append(
      svgNode('line', {
        x1: a[0],
        y1: a[1],
        x2: b[0],
        y2: b[1],
        stroke: 'var(--wc-text)',
        'vector-effect': 'non-scaling-stroke',
      }),
    )

svg.append(
      svgNode('rect', {
        x: 18,
        y: 12 + i * height,
        width: 444,
        height,
        fill: layer?.color || 'var(--wc-border)',
      }),
    )

navHost.replaceChildren(
        el('span', { class: 'p-nav-label' }, 'WORKSPACE'),
        ...registry.primaryNav.map(({ key, label, icon }) =>
          button(label, `domain:${key}`, icon, {
            'aria-pressed': String(info.selectedNavigation === key),
          }),
        ),
        button('', 'hide-editor', 'close', {
          'aria-label': 'Hide navigation and workflow editor',
        }),
      )

viewbar.replaceChildren(
        el(
          'div',
          { class: 'p-actions' },
          state.editorHidden ? button('Restore panel', 'expand-empty', 'process') : null,
          registry.viewModes.map(({ key, label }) =>
            button(label, `mode:${key}`, null, {
              disabled: narrow() && key !== 'single',
              'aria-pressed': String(mode === key),
              title: narrow() ? 'Tablet / phone use Single' : '',
            }),
          ),
        ),
        el(
          'div',
          { class: 'p-actions' },
          registry.views
            .filter(({ key }) => key !== 'section')
            .map(({ key, label, icon }) =>
              button(label, `view:${key}`, icon, {
                'aria-pressed': String(mode === 'single' && state.view === key),
              }),
            ),
          narrow()
            ? button('Section', 'mobile-section', 'section', {
                'aria-pressed': String(state.view === 'section'),
              })
            : button('Section dock', 'section', 'section', {
                'aria-pressed': String(state.section),
              }),
        ),
      )

makeButton(root, 'workstation-rail-button', meta.icon, {
        title: meta.label,
        ariaLabel: meta.label,
        dataset: { tool: name, label: meta.label },
      })

makeButton(root, 'workstation-view-tab workstation-layout-tab', 'Overview', {
      title: 'Show Main, Mask and 3D together',
      ariaLabel: 'Overview',
    })

makeButton(root, 'workstation-view-tab workstation-layout-tab', 'Split', {
      title: 'Compare any two of Main, Mask and 3D',
      ariaLabel: 'Split',
    })

makeButton(root, 'mini-btn workstation-section-layers', 'Layers', {
      title: 'Show or hide the layer legend',
      ariaLabel: 'Show or hide the layer legend',
    })

makeButton(root, 'mini-btn workstation-section-collapse', 'Hide', {
      title: 'Hide Section A–B',
      ariaLabel: 'Show or hide Section A–B',
    })
